px 20px;\n  height: 72px;\n  width: 100%;\n  background-color: white;\n  border: 1px solid #ccc;\n  border-radius: 8px;\n}\n\n.TitleR h1 {\n  font-family: Arial, sans-serif;\n  font-size: 22px;\n  margin: 0;\n  line-height: 1.1;\n}\n\n.TitleR p {\n  font-family: Arial, sans-serif;\n  color: grey;\n  margin: 0;\n  line-height: 1.1;\n  font-size: 13px;\n}\n\n/* ---------- student ID input (testing only) ---------- */\n.StuIdRow {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-bottom: 20px;\n  flex-wrap: wrap;\n}\n\n.StuIdRow label {\n  font-size: 13px;\n  font-weight: 700;\n  color: #374151;\n  white-space: nowrap;\n}\n\n.StuIdRow input {\n  width: 180px;\n  border: 1px solid #d9d9d9;\n  border-radius: 8px;\n  padding: 8px 12px;\n  font-size: 13px;\n  box-sizing: border-box;\n  background-color: white;\n  margin: 0;\n}\n\n/* ---------- main interview container ---------- */\n.StudentBottomBox {\n  width: 100%;\n  background-color: white;\n  border: 1px solid #ccc;\n  border-radius: 12px;\n  padding: 24px;\n  box-sizing: border-box;\n}\n\n.StudentBottomBox h1 {\n  font-size: 22px;\n  font-weight: 700;\n  margin: 0 0 20px 0;\n  color: #1a1a2e;\n}\n\n/* ---------- course group ---------- */\n.CourseGroup {\n  margin-bottom: 32px;\n}\n\n.CourseGroup:last-child {\n  margin-bottom: 0;\n}\n\n.CourseHeading {\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: #6b7280;\n  margin: 0 0 12px 0;\n  padding-bottom: 6px;\n  border-bottom: 1px solid #e5e7eb;\n}\n\n/* ---------- interview row ---------- */\n.IntRow {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 14px 16px;\n  border: 1px solid #e5e7eb;\n  border-radius: 10px;\n  margin-bottom: 8px;\n  cursor: pointer;\n  background-color: #fafafa;\n  transition: box-shadow 0.15s ease, transform 0.15s ease;\n  gap: 12px;\n}\n\n.IntRow:hover {\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);\n  transform: translateY(-1px);\n}\n\n.IntRow.selected {\n  border-color: #2455c8;\n  background-color: #f0f4ff;\n  box-shadow: 0 0 0 2px rgba(36, 85, 200, 0.15);\n}\n\n.IntRowLeft {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  min-width: 0;\n}\n\n.IntRowIcon {\n  width: 40px;\n  height: 40px;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 700;\n  font-size: 18px;\n  color: white;\n  flex-shrink: 0;\n}\n\n.IntRowIcon.scheduled { background-color: #2455c8; }\n.IntRowIcon.completed { background-color: #43a047; }\n.IntRowIcon.ongoing   { background-color: #fb8c00; }\n\n.IntRowInfo {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n}\n\n.IntRowName {\n  font-size: 14px;\n  font-weight: 700;\n  color: #1f2937;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.IntRowMeta {\n  font-size: 12px;\n  color: #6b7280;\n}\n\n.IntRowRight {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex-shrink: 0;\n}\n\n/* ---------- status pill ---------- */\n.StatusPill {\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: 0.05em;\n  text-transform: uppercase;\n  padding: 4px 10px;\n  border-radius: 20px;\n}\n\n.StatusPill.scheduled { background-color: #dbeafe; color: #1d4ed8; }\n.StatusPill.completed { background-color: #dcfce7; color: #166534; }\n.StatusPill.ongoing   { background-color: #ffedd5; color: #9a3412; }\n\n/* ---------- start button ---------- */\n.StartBtn {\n  background: linear-gradient(90deg, blue, purple);\n  color: white;\n  border: none;\n  border-radius: 8px;\n  padding: 8px 16px;\n  font-size: 12px;\n  font-weight: 700;\n  cursor: pointer;\n  letter-spacing: 0.03em;\n  transition: opacity 0.15s, transform 0.15s;\n  white-space: nowrap;\n}\n\n.StartBtn:hover {\n  opacity: 0.88;\n  transform: translateY(-1px);\n}\n\n/* ---------- detail panel ---------- */\n.IntDetail {\n  margin-top: 20px;\n  border: 1px solid #e5e7eb;\n  border-radius: 12px;\n  background-color: white;\n  overflow: hidden;\n}\n\n.IntDetailHeader {\n  padding: 20px 24px;\n  border-bottom: 1px solid #e5e7eb;\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  gap: 16px;\n  flex-wrap: wrap;\n}\n\n.IntDetailTitle {\n  font-size: 18px;\n  font-weight: 700;\n  color: #1f2937;\n  margin: 0 0 4px 0;\n}\n\n.IntDetailSub {\n  font-size: 13px;\n  color: #6b7280;\n  margin: 0;\n}\n\n.IntDetailClose {\n  background: none;\n  border: 1px solid #d1d5db;\n  border-radius: 6px;\n  padding: 6px 12px;\n  font-size: 12px;\n  color: #6b7280;\n  cursor: pointer;\n  flex-shrink: 0;\n}\n\n.IntDetailClose:hover {\n  background-color: #f3f4f6;\n}\n\n.IntDetailBody {\n  padding: 20px 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n/* meta info row */\n.IntDetailMeta {\n  display: flex;\n  gap: 32px;\n  flex-wrap: wrap;\n}\n\n.IntDetailMetaItem {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.IntDetailMetaLabel {\n  font-size: 11px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  color: #9ca3af;\n}\n\n.IntDetailMetaValue {\n  font-size: 14px;\n  color: #1f2937;\n  font-weight: 600;\n}\n\n/* grade block (completed only) */\n.IntDetailGrade {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  padding: 16px 20px;\n  background-color: #f0f4ff;\n  border-radius: 10px;\n  border: 1px solid #c7d2fe;\n}\n\n.IntDetailGradeLetter {\n  font-size: 2.6rem;\n  font-weight: 800;\n  color: #2455c8;\n  line-height: 1;\n}\n\n.IntDetailGradePercent {\n  font-size: 1.2rem;\n  color: #6b7280;\n  font-weight: 600;\n}\n\n/* transcript + logs */\n.IntDetailContentRow {\n  display: flex;\n  gap: 16px;\n}\n\n.IntDetailTranscript {\n  flex: 2;\n  border: 1px solid #e5e7eb;\n  border-radius: 8px;\n  overflow: hidden;\n}\n\n.IntDetailLogs {\n  flex: 1;\n  border: 1px solid #e5e7eb;\n  border-radius: 8px;\n  overflow: hidden;\n}\n\n.IntDetailSectionHead {\n  padding: 10px 14px;\n  border-bottom: 1px solid #e5e7eb;\n  font-size: 13px;\n  font-weight: 700;\n  color: #374151;\n  background-color: #f9fafb;\n}\n\n.IntDetailSectionBody {\n  padding: 14px;\n  max-height: 280px;\n  overflow-y: auto;\n  font-size: 13px;\n  color: #374151;\n  white-space: pre-wrap;\n  line-height: 1.6;\n}\n\n.LogItem {\n  padding: 8px 10px;\n  background-color: #f5f7fa;\n  border-radius: 6px;\n  font-size: 12px;\n  color: #374151;\n  margin-bottom: 6px;\n}\n\n/* feedback block */\n.IntDetailFeedback {\n  border: 1px solid #e5e7eb;\n  border-radius: 8px;\n  overflow: hidden;\n}\n\n/* upload block (scheduled + allowsUpload) */\n.IntDetailUpload {\n  border: 2px dashed #d1d5db;\n  border-radius: 10px;\n  padding: 20px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n  background-color: #fafafa;\n}\n\n.IntDetailUpload p {\n  font-size: 13px;\n  color: #6b7280;\n  margin: 0;\n  text-align: center;\n}\n\n.UploadBtn {\n  background: none;\n  border: 1px solid #d1d5db;\n  border-radius: 8px;\n  padding: 8px 18px;\n  font-size: 13px;\n  font-weight: 600;\n  color: #374151;\n  cursor: pointer;\n  transition: background-color 0.15s;\n}\n\n.UploadBtn:hover {\n  background-color: #f3f4f6;\n}\n\n.UploadedFile {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  width: 100%;\n  padding: 8px 12px;\n  background-color: #f0fdf4;\n  border: 1px solid #bbf7d0;\n  border-radius: 8px;\n  font-size: 13px;\n  color: #166534;\n  box-sizing: border-box;\n}\n\n.UploadedFile button {\n  background: none;\n  border: none;\n  color: #9ca3af;\n  cursor: pointer;\n  font-size: 16px;\n  padding: 0;\n  line-height: 1;\n  margin: 0;\n  width: auto;\n}\n\n/* empty state */\n.EmptyState {\n  text-align: center;\n  padding: 40px 20px;\n  color: #9ca3af;\n  font-size: 14px;\n}\n\n\nRUBRIC:\n%PDF-1.7\r\n%����\r\n1 0 obj\r\n<</Type/Catalog/Pages 2 0 R/Lang(en) /StructTreeRoot 57 0 R/Outlines 44 0 R/MarkInfo<</Marked true>>/Metadata 586 0 R/ViewerPrefer