p()\n        continent = Continent(name) \n        regions = countries.split(\',\')\n        \n        for region in regions:\n            region_name, region_code = region.split(\'-\')\n            region_name = region_name.strip()\n            region_code = region_code.strip()\n            continent.process(region_name, region_code, months_list)\n        \n        print(continent)\n        print()\n    \n\nclass Arrival:\n    \n    def __init__(self, month = \'JAN\', number_of_arrivals = 0):\n        self.month = month\n        self.number_of_arrivals = number_of_arrivals\n    \n    def get_number_of_arrivals(self):\n        return self.number_of_arrivals\n        \n    def __str__(self):\n        blank = (7 - len(str(self.number_of_arrivals))) * \' \'\n        return f\'{self.month}:{blank}{self.number_of_arrivals}\'\n       \nclass Region:\n    \n    def __init__(self, region_name, region_code, months_list):\n        self.region_name = region_name\n        self.region_code = region_code\n        self.months_list = months_list\n        self.arrivals_list = []\n        self.process(months_list)\n    \n    def get_arrivals_list(self):\n        return self.arrivals_list\n    \n    def add_arrival(self, month, value):\n        self.arrivals_list.append(Arrival(month, value))\n    \n    def get_total_number_of_arrivals(self):\n        self.total_number_arrivals = 0\n        \n        for arrival in self.arrivals_list:\n            self.total_number_arrivals+= arrival.get_number_of_arrivals()\n            \n        return self.total_number_arrivals\n    \n    def __str__(self):\n        return f\'{self.region_code}({self.get_total_number_of_arrivals()})\' + \'\\t\' + \'\\t\'.join(str(arrival) for arrival in self.arrivals_list)\n        \n    def process_data_per_month(self, month_name):\n        arrivals_per_month = 0\n        input_file = open(f\'{self.region_code}_{month_name}.txt\', \'r\')\n        \n        for line in input_file.readlines():\n            arrivals_per_month  += int(line)\n            \n        self.arrivals_list.append(Arrival(month_name, arrivals_per_month))\n        input_file.close()\n    \n    def process(self, months_list):\n        \n        for month in months_list:\n            self.process_data_per_month(month)\n            \nclass Continent:\n    \n    def __init__(self, name):\n        self.name = name\n        self.regions_list = []\n    \n    def process(self, region_name, region_code, months_list):\n        self.regions_list.append(Region(region_name, region_code, months_list))\n    \n    def get_regions_list(self):\n        return self.regions_list\n    \n    def get_total_arrivals(self):\n        total_arrivals = 0\n        \n        for region in self.regions_list:\n           total_arrivals+= region.get_total_number_of_arrivals()\n           \n        return total_arrivals\n    \n    def __str__(self):\n        script = \'\'\n        cont = f\'{self.name}(Total: {self.get_total_arrivals()})\'\n        for region in self.regions_list:\n            script += \'\\n\' + str(region)\n        return cont + script\n\n\nRUBRIC:\n266000\n900\n60\n\n\nSTUDENT:\n'),(42,'BRIEF:\n#Aidan Corless\n#This program reads input from the user and data from text files to neatly display arrival statistics for multiple continents.\n\n\ndef main():\n    months_list = [\'NOV\', \'DEC\', \'JAN\', \'FEB\']\n    filename = input(\'Enter a filename: \')\n    print(\'NZ-resident traveller arrivals\\n\')\n    input_file = open(filename, \'r\')\n    \n    for line in input_file.readlines():\n        name, countries = line.split(\':\')\n        name = name.strip()\n        continent = Continent(name) \n        regions = countries.split(\',\')\n        \n        for region in regions:\n            region_name, region_code = region.split(\'-\')\n            region_name = region_name.strip()\n            region_code = region_code.strip()\n            continent.process(region_name, region_code, months_list)\n        \n        print(continent)\n        print()\n    \n\nclass Arrival:\n    \n    def __init__(self, month = \'JAN\', number_of_arrivals = 0):\n        self.month = month\n        self.number_of_arrivals = number_of_arrivals\n    \n    def get_number_of_arrivals(self):\n        return self.number_of_arrivals\n        \n    def __str__(self):\n        blank = (7 - len(str(self.number_of_arrivals))) * \' \'\n        return f\'{self.month}:{blank}{self.number_of_arrivals}\'\n       \nclass Region:\n    \n    def __init__(self, region_name, region_code, months_list):\n        self.region_name = region_name\n        self.region_code = region_code\n        self.months_list = months_list\n        self.arrivals_list = []\n        self.process(months_list)\n    \n    def get_arrivals_list(self):\n        return self.arrivals_list\n    \n    def add_arrival(self, month, value):\n        self.arrivals_list.append(Arrival(month, value))\n    \n    def get_total_number_of_arrivals(self):\n        self.total_number_arrivals = 0\n        \n        for arrival in self.arrivals_list:\n            self.total_number_arrivals+= arrival.get_number_of_arrivals()\n            \n        return self.total_number_arrivals\n    \n    def __str__(self):\n        return f\'{self.region_code}({self.get_total_number_of_arrivals()})\' + \'\\t\' + \'\\t\'.join(str(arrival) for arrival in self.arrivals_list)\n        \n    def process_data_per_month(self, month_name):\n        arrivals_per_month = 0\n        input_file = open(f\'{self.region_code}_{month_name}.txt\', \'r\')\n        \n        for line in input_file.readlines():\n            arrivals_per_month  += int(line)\n            \n        self.arrivals_list.append(Arrival(month_name, arrivals_per_month))\n        input_file.close()\n    \n    def process(self, months_list):\n        \n        for month in months_list:\n            self.process_data_per_month(month)\n            \nclass Continent:\n    \n    def __init__(self, name):\n        self.name = name\n        self.regions_list = []\n    \n    def process(self, region_name, region_code, months_list):\n        self.regions_list.append(Region(region_name, region_code, months_list))\n    \n    def get_regions_list(self):\n        return self.regions_list\n    \n    def get_total_arrivals(self):\n        total_arrivals = 0\n        \n        for region in self.regions_list:\n           total_arrivals+= region.get_total_number_of_arrivals()\n           \n        return total_arrivals\n    \n    def __str__(self):\n        script = \'\'\n        cont = f\'{self.name}(Total: {self.get_total_arrivals()})\'\n        for region in self.regions_list:\n            script += \'\\n\' + str(region)\n        return cont + script\n\n\nRUBRIC:\n266000\n900\n60\n\n\nSTUDENT:\n'),(43,'BRIEF:\n226000\n180\n\n\nRUBRIC:\n226000\n180\n\n\nSTUDENT:\n'),(44,'BRIEF:\n�PNG\r\n\Z\n\0\0\0\rIHDR\0\0�\0\0L\0\0\0q�6\0\0OiCCPICC Profile\0\0H��WXS��[R!�\"%�&�H	 %�@zD%$B�1!���E�.\"XVt��Ȣ(�+�bw-�e]\\*oB\0]�����͝��s�sΝ{�\0�N�T��j�\'ɗņ�&\'��H�p�P`�ȥ���\0�p����@��UG��?��k���\0�h�ӅrA�G\0��RY>\0D)�-f�K�x�:2� ��J����J��m�c�?�����2��<�@�	u�0Z�,�%�C웗7C�\"�m�\r����g����7��M>?s�b,�@�\\�˟�����\\��6��g�Bc�1ü=Ι������GFA�\r\0�����J��R�&��Q[��s�O�����X!?0b#�3$��C6E�`�\r�Z.���C�q�H7dsR6#vx�2.g�Ɨ\r������I��1�,oHs*̊O��\nq`�81b\r�#�9q�C6��Y��a�\"V�%�2�$$@���eȂc����ɇc�Nf�y�C�J~V|�*W�c��+�p�uD��ñE�A��q�H���q}i~@�j,n/͍��D�!J��xyA��؂|�8U�x�4?:^�\'^���V��\0�(`M3@6��4��;UO0��\"�8��H\Z��k(�C$�q��\"P\0�O�X%\'�TWG�1ԧT�O �� �+�$#$�ǐ��#>�C.�����_d\"����,��%1�H%�pC���#��V��{��Ş���AxH�N�$ܞ..���r���C�I�:?�5�t�p��q&nqW8��3�A�;�2+�Q���\'4dGq��=�?�v�H\r{\r�e��Ώ����|sGzF���*�B؆��Ėc��s�)�֌5\0ւ5bm�q%Yq�W��l����@��k�˓UfR�\\����Q՗/���|�3�sd�̬|�1D,�D�4��������������� ̶/ܒ�\0�i����A�I8���e�_�\Z\0�	��+/��÷�\0�\0`�q���� �@<HӠ�Yp���,0,Š�A�v�j�8\Z@38~�ep܁���\0��\r�G���b��